          >
            <div class="q-pa-md">
              <WorkflowRunLogMessages
                :messages="displayed_messages[(props.row as any).id]"
                :heading-key="logMessagesHeadingKey(props.row)"
              >
                <template #actions>
                  <q-btn
                    flat
                    dense
                    no-caps
                    color="primary"
                    icon="open_in_full"
                    class="col-auto open-in-popup-btn"
                    :label="$t('wf_open_in_popup')"
                    @click.stop="openRunPopup(props.row)"
                  />
                </template>
              </WorkflowRunLogMessages>
