    :check-card-success="checkCardSuccess"
    :on-card-logs="getCardLogs"
    :workflow-changed="isWorkflowChanged"
    :workflows="workflows"
    :messages="popupRow ? displayed_messages[popupRow.id] : undefined"
    :heading-key="popupRow ? logMessagesHeadingKey(popupRow) : 'wf_card_logs'"
    :selected-node-id="selectedAdvancedNodeId"
