/**
 * Display helpers shared by the workflow log views: the run list, the inline
 * expanded row and the run popup.
 */

/**
 * AdvancedWorkflowViewer settings shared by every log view.
 *
 * A logged run is a read-only record, but it stays pannable, zoomable and
 * draggable so a large graph can be inspected. Only the minimap differs per
 * call site, so it is passed separately rather than defaulted here.
 */
export const LOG_VIEWER_OPTIONS = {
  readOnly: true,
  zoomEnabled: true,
  panEnabled: true,
  showBackground: true,
  nodesDraggable: true,
} as const;

/**
 * Icon and colour for a workflow run result, shared by the log list column and
 * the run popup header so the two cannot drift.
 *
 * A missing result is treated as a failed condition, which is how a run that
 * stopped on a condition is reported.
 */
export function getRunResultDisplay(
  result: string | null | undefined,
): { icon: string; color: string } {
  if (result === 'success') return { icon: 'check_circle', color: 'green' };
  if (result === null || result === undefined || result === 'failed_condition') {
    return { icon: 'do_not_disturb_on', color: 'orange' };
  }
  return { icon: 'cancel', color: 'red' };
}

/**
 * Identity of one rendered card in a run.
 *
 * Position is part of the key as well as the id, because the same card can
 * appear more than once in a workflow and only the clicked one is highlighted.
 */
export function cardLogKey(
  cardId: string,
  index: number | string,
  category: string,
  indexAdditionals: number | string = 0,
): string {
  return `${cardId}|${index}|${category}|${indexAdditionals}`;
}

/**
 * Where a run sits, given its position across every page.
 *
 * The popup counts runs rather than pages, so stepping or typing a number has to
 * be turned back into the page to fetch and the row within it. Kept separate
 * from the fetching so the arithmetic can be tested on its own.
 *
 * @param runNumber one-based position across all pages, clamped into range
 * @param pageSize rows the endpoint returns per page
 * @param totalRuns total across all pages, from the endpoint
 */
export function runPageLocation(
  runNumber: number,
  pageSize: number,
  totalRuns: number,
): { runNumber: number; page: number; rowIndex: number } {
  const highest = Math.max(1, totalRuns || 1);
  const requested = Math.trunc(runNumber) || 1;
  const clamped = Math.min(Math.max(1, requested), highest);

  return {
    runNumber: clamped,
    page: Math.floor((clamped - 1) / pageSize) + 1,
    rowIndex: (clamped - 1) % pageSize,
  };
}
