<template>
  <div>
    <div :class="['small-heading row items-center no-wrap', { 'small-heading--large': largeHeading }]">
      <div class="col">{{ $t(headingKey) }}</div>
      <slot name="actions" />
    </div>
    <div v-if="messages">
      <div v-for="(message, index) in messages" :key="index">
        <span v-if="message.translation_key" class="card-message">{{
          $t('wf_log_' + message.translation_key, translateDataLocal(message.data))
        }}</span>
        <span v-else class="card-message">{{ message.message }}</span>
      </div>
    </div>
    <div v-else>
      {{ $t('wf_card_logs_message') }}
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import { translateData, DisplayMessage } from 'src/pages/WorkflowBuilder/composables/useNodeLogMessage';

export default defineComponent({
  name: 'WorkflowRunLogMessages',
  props: {
    /** Resolved log lines for the selected card, or undefined when none is selected. */
    messages: {
      type: Array as PropType<DisplayMessage[] | undefined>,
      default: undefined,
    },
    /** Translation key for the pane heading: card logs, or workflow logs for a changed workflow. */
    headingKey: {
      type: String,
      default: 'wf_card_logs',
    },
    /** Larger heading for the popup, where the pane has far more room. */
    largeHeading: {
      type: Boolean,
      default: false,
    },
  },
  methods: {
    translateDataLocal(data: Record<string, string> | undefined) {
      return translateData(data);
    },
  },
});
</script>

