<template>
  <q-dialog
    :model-value="modelValue"
    @update:model-value="$emit('update:modelValue', $event)"
    @show="refitToken += 1"
  >
    <q-card v-if="row" class="run-popup column no-wrap">
      <q-card-section class="run-popup__header row items-center no-wrap q-gutter-sm">
        <q-icon
          :name="getRunResultDisplay(row.result).icon"
          :color="getRunResultDisplay(row.result).color"
          size="sm"
          class="col-auto"
        />
        <div class="text-subtitle1 col-auto">{{ row.workflow_name }}</div>
        <div class="run-popup__meta col-auto">
          {{ formatDateAccordingToPreference(row.created_on) }}
        </div>
        <div class="run-popup__meta col-auto">{{ row.run_time_seconds }} s</div>
        <div class="col"></div>

        <div class="run-popup__nav row items-center no-wrap col-auto">
          <q-btn
            flat
            dense
            icon="chevron_left"
            :disable="runNumber <= 1"
            @click="$emit('go-to-run', runNumber - 1)"
          >
            <q-tooltip>{{ $t('wf_previous_run') }}</q-tooltip>
          </q-btn>
          <input
            class="run-popup__run-input"
            inputmode="numeric"
            :value="runInput"
            :aria-label="$t('wf_next_run')"
            @input="runInput = ($event.target as HTMLInputElement).value"
            @keyup.enter="commitRunInput"
            @blur="commitRunInput"
          />
          <div class="run-popup__total">/ {{ totalRuns }}</div>
          <q-btn
            flat
            dense
            icon="chevron_right"
            :disable="runNumber >= totalRuns"
            @click="$emit('go-to-run', runNumber + 1)"
          >
            <q-tooltip>{{ $t('wf_next_run') }}</q-tooltip>
          </q-btn>
        </div>

        <q-btn flat dense icon="close" class="col-auto" v-close-popup>
          <q-tooltip>{{ $t('close') }}</q-tooltip>
        </q-btn>
      </q-card-section>

      <div class="col column no-wrap relative-position run-popup__body-wrap">
        <q-splitter
          v-model="splitter"
          :limits="[40, 85]"
          :separator-style="{ width: '8px' }"
          class="col run-popup__body"
        >
        <template v-slot:separator>
          <div class="run-popup__grip">
            <span class="run-popup__grip-pill">
              <q-icon name="swap_horiz" size="20px" />
            </span>
            <q-tooltip>{{ $t('wf_drag_to_resize') }}</q-tooltip>
          </div>
        </template>

        <template v-slot:before>
          <div class="run-popup__content">
            <WorkflowRunContent
              :fill="true"
              :refit-token="refitToken"
              :row="row"
              :transformed-data="transformedData"
              :selected-node-id="selectedNodeId"
              :show-minimap="true"
              :check-card-success="checkCardSuccess"
              :on-card-logs="onCardLogs"
              :workflow-changed="workflowChanged"
              :workflows="workflows"
              @node-click="(nodeId: string) => $emit('node-click', nodeId)"
            />
          </div>
        </template>

          <template v-slot:after>
            <div class="q-pa-md run-popup__logs">
              <WorkflowRunLogMessages
                :messages="messages"
                :heading-key="headingKey"
                :large-heading="true"
              />
            </div>
          </template>
        </q-splitter>

        <q-inner-loading :showing="loading" color="primary" />
      </div>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, PropType, ref } from 'vue';
import dateUtils from 'src/utils/date';
import WorkflowRunLogMessages from 'src/pages/WorkflowBuilder/workflowLogs/WorkflowRunLogMessages.vue';
import WorkflowRunContent from 'src/pages/WorkflowBuilder/workflowLogs/WorkflowRunContent.vue';
import { getRunResultDisplay } from 'src/pages/WorkflowBuilder/workflowLogs/workflowLogDisplay';
import { DisplayMessage } from 'src/pages/WorkflowBuilder/composables/useNodeLogMessage';

export default defineComponent({
  name: 'WorkflowRunPopup',
  components: { WorkflowRunLogMessages, WorkflowRunContent },
  mixins: [dateUtils],
  props: {
    modelValue: { type: Boolean, default: false },
    /** The log row being shown, or null while the dialog is closed. */
    row: { type: Object as PropType<any | null>, default: null },
    /** Position of this run across every page, which is what the counter shows. */
    runNumber: { type: Number, default: 1 },
    /** True while the run being navigated to is still being fetched. */
    loading: { type: Boolean, default: false },
    totalRuns: { type: Number, default: 0 },
    /** VueFlow nodes, edges and execution data, or null when the run has no diagram. */
    transformedData: { type: Object as PropType<any | null>, default: null },
    messages: { type: Array as PropType<DisplayMessage[] | undefined>, default: undefined },
    headingKey: { type: String, default: 'wf_card_logs' },
    selectedNodeId: { type: String as PropType<string | null>, default: null },
    /** Passed straight through to WorkflowRunContent, which reads the log caches. */
    checkCardSuccess: { type: Function as PropType<(...args: any[]) => any>, required: true },
    onCardLogs: { type: Function as PropType<(...args: any[]) => any>, required: true },
    workflowChanged: { type: Function as PropType<(runId: string) => any>, required: true },
    workflows: { type: Object as PropType<Record<string, any>>, default: () => ({}) },
  },
  emits: ['update:modelValue', 'go-to-run', 'node-click'],
  setup() {
    return { getRunResultDisplay, splitter: ref(70) };
  },
  data() {
    return {
      /** Local copy, so a half-typed number does not navigate on every keystroke. */
      runInput: this.runNumber as number | string | null,
      /**
       * Bumped once the dialog has finished showing. The canvas has no usable
       * size while it animates in, and edges measured then attach to the wrong
       * handle bounds.
       */
      refitToken: 0,
    };
  },
  watch: {
    runNumber(value: number) {
      this.runInput = value;
      // A different run means a different graph in an already-sized dialog.
      this.refitToken += 1;
    },
  },
  methods: {
    commitRunInput() {
      const parsed = Number(this.runInput);
      if (!Number.isFinite(parsed) || parsed === this.runNumber) {
        this.runInput = this.runNumber;
        return;
      }
      this.$emit('go-to-run', parsed);
    },
  },
});
</script>

