<template>
  <div :class="['text-subtitle2 q-pa-md full-width', { 'run-content--fill': fill }]">
    <WorkflowRunExternalLogs
      v-if="row.workflow_name.includes('EXTERNAL_LOGS')"
      :log-groups="row.logs"
    />
    <!-- Workflow Flow Visualization (v3 workflows) -->
    <div
      v-else-if="row.workflow_version === 3 && hasWorkflowData(row)"
      :class="['workflow-flow-container', { 'workflow-flow-container--fill': fill }]"
    >
      <AdvancedWorkflowViewer
        v-if="transformedData"
        v-bind="LOG_VIEWER_OPTIONS"
        :nodes="transformedData.nodes"
        :edges="transformedData.edges"
        :executionData="transformedData.executionData"
        :selectedNodeId="selectedNodeId"
        :refitToken="refitToken"
        :showMinimap="showMinimap"
        @node-click="(nodeId: string) => $emit('node-click', nodeId)"
      />
    </div>
    <div
      v-else-if="
        ![undefined, null].includes(
          (row as any).workflow_data,
        ) &&
        (row as any).workflow_data != undefined &&
        (row as any).workflow_data.when_condition.card_logs !=
          undefined
      "
    >
      <WorkflowRunCardList
        heading-key="wf_when"
        :cards="loggedWhenCards"
        :run-id="(row as any).id"
        category="when"
        :selected-card-key="selectedCardKey"
        :check-card-success="checkCardSuccess"
        @select="selectCard"
      />

      <div
        v-if="
          !row.workflow_version ||
          row.workflow_version == 1
        "
      >
        <WorkflowRunCardList
          v-for="group in v1Groups"
          :key="group.category"
          :heading-key="group.headingKey"
          :cards="group.cards"
          :run-id="(row as any).id"
          :category="group.category"
          :selected-card-key="selectedCardKey"
          :check-card-success="checkCardSuccess"
          @select="selectCard"
        />
      </div>
      <!-- <div v-else-if="row.workflow_version == 2"> -->
      <div v-else>
        <div class="card-category-text">{{ $t('wf_and') }}</div>
        <div
          class="full-width"
          v-for="(item, index) in (row as any).workflow_data
            .and_conditions"
          :key="item.id + '_' + item.card_version + '_' + index"
        >
          <div
            v-if="
              row.workflow_data.and_condition_break == null ||
              index <= row.workflow_data.and_condition_break
            "
          >
            <GenericCard
              :card_result="
                checkCardSuccess((row as any).id, index, 'and')
              "
              :item="item"
              :version="item.version"
              :class="{ 'card-log-selected': isSelectedCard(
                  item.id,
                  (row as any).id,
                  index,
                  'and',
                ) }"
              @click="
                selectCard(
                  item.id,
                  (row as any).id,
                  index,
                  'and',
                )
              "
            />
          </div>
        </div>
        <div>
          <q-markup-table
            :separator="'none'"
            wrap-cells
            flat
            square
            class="markup-table-branching"
            v-if="row.workflow_version == 2"
          >
            <tbody>
              <tr>
                <td>
                  <div class="card-category-text">
                    {{ $t('wf_and_continued') }}
                  </div>
                  <template
                    v-for="(item, index) in row.workflow_data
                      .and_conditions"
                    :key="
                      item.id +
                      '_' +
                      item.card_version +
                      '_' +
                      item.uuid
                    "
                  >
                    <div
                      v-if="
                        row.workflow_data.and_condition_break !=
                          null &&
                        index >
                          row.workflow_data.and_condition_break
                      "
                    >
                      <GenericCard
                        :card_result="
                          checkCardSuccess(
                            (row as any).id,
                            index,
                            'and',
                          )
                        "
                        :item="item"
                        :version="item.version"
                        :class="{ 'card-log-selected': isSelectedCard(
                            item.id,
                            (row as any).id,
                            index,
                            'and',
                          ) }"
                        @click="
                          selectCard(
                            item.id,
                            (row as any).id,
                            index,
                            'and',
                          )
                        "
                      />
                    </div>
                  </template>

                  <div class="card-category-text">
                    {{ $t('wf_then') }}
                  </div>
                  <template
                    v-for="(item, index) in row.workflow_data
                      .then_conditions"
                    :key="
                      item.id +
                      '_' +
                      item.card_version +
                      '_' +
                      item.uuid
                    "
                  >
                    <div class="selected-card">
                      <GenericCard
                        :card_result="
                          checkCardSuccess(
                            (row as any).id,
                            index,
                            'then',
                          )
                        "
                        :item="item"
                        :version="item.version"
                        :class="{ 'card-log-selected': isSelectedCard(
                            item.id,
                            (row as any).id,
                            index,
                            'then',
                          ) }"
                        @click="
                          selectCard(
                            item.id,
                            (row as any).id,
                            index,
                            'then',
                          )
                        "
                      />
                    </div>
                  </template>
                </td>
                <td
                  v-for="(
                    itemAdditionalCondition, indexAdditionals
                  ) in row.workflow_data
                    .additional_and_conditions"
                  :key="indexAdditionals"
                >
                  <div class="card-category-text">
                    {{
                      row.workflow_data
                        .additional_and_conditions.length ==
                        (indexAdditionals as number) + 1 &&
                      row.workflow_data
                        .additional_and_conditions[indexAdditionals]
                        .length == 0
                        ? $t('wf_alternate_conditions_else')
                        : $t('wf_alternate_conditions')
                    }}
                  </div>
                  <template
                    v-for="(item, index) in row.workflow_data
                      .additional_and_conditions[indexAdditionals]"
                    :key="
                      item.id +
                      '_' +
                      item.card_version +
                      '_' +
                      item.uuid
                    "
                  >
                    <div class="selected-card">
                      {{ item.indexAdditionals }}
                      <GenericCard
                        :card_result="
                          checkCardSuccess(
                            (row as any).id,
                            index,
                            'additional_conditions',
                            (indexAdditionals as number),
                          )
                        "
                        :item="item"
                        :version="item.version"
                        :class="{ 'card-log-selected': isSelectedCard(
                            item.id,
                            (row as any).id,
                            index,
                            'additional_conditions',
                            (indexAdditionals as number),
                          ) }"
                        @click="
                          selectCard(
                            item.id,
                            (row as any).id,
                            index,
                            'additional_conditions',
                            (indexAdditionals as number),
                          )
                        "
                      />
                    </div>
                  </template>
                  <div class="card-category-text">
                    {{ $t('wf_alternate_executions') }}
                  </div>
                  <template
                    v-for="(item, index) in row.workflow_data
                      .additional_then_executions[indexAdditionals]"
                    :key="
                      item.id +
                      '_' +
                      item.card_version +
                      '_' +
                      item.uuid
                    "
                  >
                    <div class="selected-card">
                      {{ item.indexAdditionals }}
                      <GenericCard
                        :card_result="
                          checkCardSuccess(
                            (row as any).id,
                            index,
                            'additional_executions',
                            (indexAdditionals as number),
                          )
                        "
                        :item="item"
                        :version="item.version"
                        :class="{ 'card-log-selected': isSelectedCard(
                            item.id,
                            (row as any).id,
                            index,
                            'additional_executions',
                            (indexAdditionals as number),
                          ) }"
                        @click="
                          selectCard(
                            item.id,
                            (row as any).id,
                            index,
                            'additional_executions',
                            (indexAdditionals as number),
                          )
                        "
                      />
                    </div>
                  </template>
                </td>
              </tr>
            </tbody>
          </q-markup-table>
        </div>
      </div>
    </div>

    <div v-else>
      <div
        v-if="workflowChanged((row as any).id)"
        class="small-heading"
      >
        {{ $t('wf_workflow_changed') }}
      </div>

      <WorkflowRunCardList
        v-for="group in changedWorkflowGroups"
        :key="group.category"
        :heading-key="group.headingKey"
        :cards="group.cards"
        :run-id="(row as any).id"
        :category="group.category"
        :selected-card-key="selectedCardKey"
        :check-card-success="checkCardSuccess"
        @select="selectCard"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import GenericCard from 'src/pages/WorkflowBuilder/workflowLogs/generic_card_logs.vue';
import WorkflowRunCardList from 'src/pages/WorkflowBuilder/workflowLogs/WorkflowRunCardList.vue';
import WorkflowRunExternalLogs from 'src/pages/WorkflowBuilder/workflowLogs/WorkflowRunExternalLogs.vue';
import { cardLogKey } from 'src/pages/WorkflowBuilder/workflowLogs/workflowLogDisplay';
import AdvancedWorkflowViewer from 'src/pages/WorkflowBuilder/WorkflowComponnets/AdvancedWorkflowViewer.vue';
import { LOG_VIEWER_OPTIONS } from 'src/pages/WorkflowBuilder/workflowLogs/workflowLogDisplay';

/**
 * The body of one workflow run: the advanced diagram, the standard card lists,
 * or the external-log rows, whichever the run carries.
 *
 * Rendered both inline under an expanded table row and inside the run popup, so
 * the two views cannot drift apart. Log lookups stay with the owner of the log
 * data and are passed in, because they read caches this component does not hold.
 */
export default defineComponent({
  name: 'WorkflowRunContent',
  components: { GenericCard, AdvancedWorkflowViewer, WorkflowRunCardList, WorkflowRunExternalLogs },
  props: {
    row: { type: Object as PropType<any>, required: true },
    /** VueFlow nodes, edges and execution data for a version 3 run. */
    transformedData: { type: Object as PropType<any | null>, default: null },
    showMinimap: { type: Boolean, default: false },
    /** Stretch the diagram to the available height instead of its fixed inline height. */
    fill: { type: Boolean, default: false },
    /** Forwarded to the viewer so a host can refit once its canvas is laid out. */
    refitToken: { type: Number, default: 0 },
    selectedNodeId: { type: String as PropType<string | null>, default: null },
    /** Whether the card at this position succeeded; reads the run log cache. */
    checkCardSuccess: { type: Function as PropType<(...args: any[]) => any>, required: true },
    /** Load the log lines for a card into the log pane. */
    onCardLogs: { type: Function as PropType<(...args: any[]) => any>, required: true },
    /** Whether the workflow was modified after this run, so cards cannot be matched. */
    workflowChanged: { type: Function as PropType<(runId: string) => any>, required: true },
    /** Workflow definitions by id, used to read the version a run executed. */
    workflows: { type: Object as PropType<Record<string, any>>, default: () => ({}) },
  },
  emits: ['node-click'],
  computed: {
    /** The WHEN card as a single-item list, so it renders through the same list component. */
    loggedWhenCards(): any[] {
      const card = (this.row as any)?.workflow_data?.when_condition;
      return card ? [card] : [];
    },

    /** AND and THEN groups of a version 1 run, read from its own log data. */
    v1Groups(): Array<{ headingKey: string; category: string; cards: any[] }> {
      const data = (this.row as any)?.workflow_data ?? {};
      return [
        { headingKey: 'wf_and', category: 'and', cards: data.and_conditions ?? [] },
        { headingKey: 'wf_then', category: 'then', cards: data.then_conditions ?? [] },
      ];
    },

    /**
     * Groups of a run whose workflow changed afterwards: the cards can no longer
     * come from the run, so they are read from the workflow definition instead.
     */
    changedWorkflowGroups(): Array<{ headingKey: string; category: string; cards: any[] }> {
      const workflow = this.workflows?.[(this.row as any)?.workflow_id];
      if (!workflow) return [];
      return [
        { headingKey: 'wf_when', category: 'when', cards: workflow.when_condition ? [workflow.when_condition] : [] },
        { headingKey: 'wf_and', category: 'and', cards: workflow.and_conditions ?? [] },
        { headingKey: 'wf_then', category: 'then', cards: workflow.then_conditions ?? [] },
      ];
    },
  },
  data() {
    return {
      /** Which card's logs the pane is showing, so it can be highlighted. */
      selectedCardKey: null as string | null,
    };
  },
  watch: {
    'row.id'() {
      this.selectedCardKey = null;
    },
  },
  setup() {
    return { LOG_VIEWER_OPTIONS };
  },
  methods: {
    /**
     * Identifies one rendered card. Position matters as well as id, because the
     * same card can appear more than once in a workflow.
     */
    cardKey(cardId: string, _runId: string, index: any, category: string, indexAdditionals = 0): string {
      return cardLogKey(cardId, index, category, indexAdditionals);
    },

    selectCard(cardId: string, runId: string, index: any, category: string, indexAdditionals = 0) {
      this.selectedCardKey = this.cardKey(cardId, runId, index, category, indexAdditionals);
      this.onCardLogs(cardId, runId, index, category, indexAdditionals);
    },

    isSelectedCard(cardId: string, runId: string, index: any, category: string, indexAdditionals = 0): boolean {
      return this.selectedCardKey === this.cardKey(cardId, runId, index, category, indexAdditionals);
    },

    hasWorkflowData(logEntry: any): boolean {
      return (
        logEntry.workflow_version === 3 &&
        logEntry.workflow_data?.nodes?.length > 0
      );
    },
  },
});
</script>

