<template>
  <div>
    <div class="card-category-text">{{ $t(headingKey) }}</div>
    <div
      class="full-width"
      v-for="(item, index) in cards"
      :key="item.id + '_' + item.card_version + '_' + index"
    >
      <div>
        <GenericCard
          :card_result="checkCardSuccess(runId, index, category)"
          :item="item"
          :version="item.version"
          :class="{
            'card-log-selected': selectedCardKey === cardLogKey(item.id, index, category),
          }"
          @click="$emit('select', item.id, runId, index, category)"
        />
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import GenericCard from 'src/pages/WorkflowBuilder/workflowLogs/generic_card_logs.vue';
import { cardLogKey } from 'src/pages/WorkflowBuilder/workflowLogs/workflowLogDisplay';

/**
 * One WHEN / AND / THEN group of a standard workflow run: its heading and its
 * cards, with the click and highlight wiring.
 *
 * The cards come from the caller because a run reads them from its own log data
 * while a run whose workflow has since changed reads them from the workflow
 * definition instead.
 */
export default defineComponent({
  name: 'WorkflowRunCardList',
  components: { GenericCard },
  props: {
    /** Translation key for the group heading, e.g. wf_when. */
    headingKey: { type: String, required: true },
    cards: { type: Array as PropType<any[]>, default: () => [] },
    runId: { type: String, required: true },
    /** Run category the cards belong to: when, and, or then. */
    category: { type: String, required: true },
    selectedCardKey: { type: String as PropType<string | null>, default: null },
    /** Whether the card at this position succeeded; reads the run log cache. */
    checkCardSuccess: { type: Function as PropType<(...args: any[]) => any>, required: true },
  },
  emits: ['select'],
  setup() {
    return { cardLogKey };
  },
});
</script>

<style scoped lang="scss">
.card-category-text {
  color: $primary;
  font-size: 15px;
}

.card-log-selected {
  border-radius: 8px;
  box-shadow: 0 0 0 2px $primary;
}
</style>
